{"base": "c0ee56a5", "workflow": "RENOM, paiement : événements Stripe", "workflow_id": "kmQ9W6URHXccXmAa", "sous_workflow": {"nom": "RENOM, facture : envoi au client", "fichier": "n8n/renom-facture-envoi.json"}, "paquet": {"RENOM, paiement : événements Stripe": {"Vérifier et traduire": {"jsCode": "// Paiement Stripe : vérification de la signature d'un événement et traduction en mise à jour de la table abonnements (espace/supabase/schema.sql,
// fonction appliquer_evenement_stripe), ou en commande d'une option ponctuelle (table commandes_options, fonction enregistrer_commande_option, 22/10/2026). Une seule source : recopiée mot pour mot dans le nœud Code de n8n/renom-stripe-webhook.json
// (n8n/build_stripe.py) et exécutée par moteur/tests/test_stripe_webhook.js. Aucune clé ici : le secret du webhook vient de la variable n8n RENOM_STRIPE_WEBHOOK_SECRET.
//
// Signature (bibliothèque officielle de Stripe, module Stripe::Webhook::Signature, lu le 14/10/2026 : https://rubydoc.info/gems/stripe/Stripe/Webhook/Signature) :
//   en-tête « Stripe-Signature: t=<horodatage>,v1=<signature>[,v1=...] » ; schéma attendu « v1 » ; signature = HMAC-SHA256 en hexadécimal, clé = secret
//   du point de terminaison (whsec_...), message = « <t>.<corps brut> » (« timestamped_payload = "#{timestamp.to_i}.#{payload}" »). Le corps doit être
//   le corps BRUT reçu, octet pour octet (un JSON relu puis réécrit ne vérifie plus). Fraîcheur : 300 s, valeur de RENOM (la bibliothèque n'en impose pas).
// Formes des objets (NON CONFIRMÉ contre un vrai compte, aucun appel fait) : l'identifiant d'abonnement d'une facture est lu à deux endroits,
// invoice.subscription (anciennes versions de l'API) et invoice.parent.subscription_details.subscription (versions récentes) ; de même pour ses métadonnées.
const crypto = require("crypto");
const TOLERANCE_S = 300;
const STATUTS = ["en_attente", "actif", "impaye", "resilie"];
// Offres reconnues dans les métadonnées : les trois offres en vente (16/10/2026), plus « croissance » et « signature » (retirées) pour un ancien abonnement éventuel.
const OFFRES_STRIPE = ["essentiel", "standard", "premium", "croissance", "signature"];
// Rythmes de paiement (formule annuelle, 16/10/2026) : « mensuel » (prix au mois, sans engagement) ou « annuel » (12 mois payés d'avance).
// « semestriel » (6 mois d'avance) n'est plus vendu et n'a jamais été souscrit : il n'est plus reconnu.
const RYTHMES = ["mensuel", "annuel"];
const RYTHME_INTERVALLE = { month: "mensuel", year: "annuel" };
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function lireEntete(entete) {
  const r = { t: null, v1: [] };
  String(entete || "").split(",").forEach(p => { const i = p.indexOf("="); if (i < 1) return; const k = p.slice(0, i).trim(), v = p.slice(i + 1).trim();
    if (k === "t") r.t = /^\d+$/.test(v) ? Number(v) : null; else if (k === "v1" && /^[0-9a-f]{64}$/i.test(v)) r.v1.push(v.toLowerCase()); });
  return r;
}

// corps : texte brut reçu ; entete : valeur de Stripe-Signature ; secret : whsec_... ; maintenant : secondes (Date.now()/1000 par défaut).
function verifierSignature(corps, entete, secret, maintenant) {
  if (!secret) return { ok: false, raison: "secret du webhook absent (RENOM_STRIPE_WEBHOOK_SECRET)" };
  if (typeof corps !== "string" || !corps) return { ok: false, raison: "corps brut absent" };
  const e = lireEntete(entete);
  if (e.t === null || !e.v1.length) return { ok: false, raison: "en-tête Stripe-Signature illisible" };
  const now = maintenant == null ? Math.floor(Date.now() / 1000) : maintenant;
  if (e.t < now - TOLERANCE_S) return { ok: false, raison: "événement trop ancien (plus de 300 s)" };
  const attendu = Buffer.from(crypto.createHmac("sha256", secret).update(e.t + "." + corps, "utf8").digest("hex"));
  const ok = e.v1.some(s => { const b = Buffer.from(s); return b.length === attendu.length && crypto.timingSafeEqual(b, attendu); });
  return ok ? { ok: true } : { ok: false, raison: "signature invalide" };
}

const id = x => (x && typeof x === "object" ? x.id : x) || null;
const offreDe = m => (m && OFFRES_STRIPE.includes(m.offre) ? m.offre : null);
// Date de Paris (AAAA-MM-JJ) d'un horodatage Stripe (secondes), décalée de n mois.
function dateParis(s, mois) {
  if (typeof s !== "number") return null;
  const p = {}; new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/Paris", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date(s * 1000)).forEach(x => { p[x.type] = +x.value; });
  const d = new Date(Date.UTC(p.year, p.month - 1 + (mois || 0), 1)), dernier = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
  d.setUTCDate(Math.min(p.day, dernier));
  return d.toISOString().slice(0, 10);
}
function abonnementDeFacture(f) {
  const det = (f.parent && f.parent.subscription_details) || f.subscription_details || {};
  return { sub: id(f.subscription) || id(det.subscription), meta: det.metadata || {} };
}
// Offre lue sur le PRIX (27/10/2026, montée d'offre en libre-service par le portail client, audit du parcours, constats 6 et 20). Le portail change
// le prix de l'abonnement, jamais ses métadonnées : « offre » reste celle du lien de paiement d'origine. L'offre réelle est donc lue sur le prix, avec
// la table de correspondance déjà écrite par outils/stripe_catalogue.py, dans cet ordre : métadonnée « offre » du prix (metadata {offre, rythme,
// renom}), clé de recherche du prix (cle_prix : boost_<offre>_mois ou boost_<offre>_an), identifiant fixe du produit (boost_<offre>), ou métadonnée
// « offre » du produit s'il est déplié. Ni frais de mise en route (boost_frais) ni option (boost_opt_*) ne donnent d'offre. Aucun identifiant de prix
// propre à un compte : les mêmes clés valent en mode test et en mode réel. Formes lues (NON CONFIRMÉ contre un vrai compte) : abonnement
// items.data[].price (objet prix), ancien items.data[].plan ; ligne de facture line.price (anciennes versions de l'API), line.plan, et
// line.pricing.price_details {price, product} (versions récentes : identifiants seuls, d'où l'identifiant fixe du produit).
const CLE_PRIX = /^boost_(essentiel|standard|premium)_(mois|an)$/, PRODUIT_OFFRE = /^boost_(essentiel|standard|premium)$/;
function offreDuPrix(p, produit) {
  if (p && typeof p === "object") {
    const m = offreDe(p.metadata); if (m) return m;
    const k = CLE_PRIX.exec(String(p.lookup_key || "")); if (k) return k[1];
    if (produit == null) produit = p.product;
  }
  if (produit && typeof produit === "object") { const m = offreDe(produit.metadata); if (m) return m; }
  const k = PRODUIT_OFFRE.exec(String(id(produit) || "")); return k ? k[1] : null;
}
const unique = l => { const u = [...new Set(l.filter(Boolean))]; return u.length === 1 ? u[0] : null; };
// Abonnement : l'offre de ses lignes (une seule ligne récurrente chez BoostImpact ; deux offres différentes : rien n'est déduit).
const offreAbonnement = s => unique((s.items && Array.isArray(s.items.data) ? s.items.data : []).map(x => offreDuPrix(x.price || x.plan)));
// Facture : lignes de montant positif ou nul seulement. Une montée d'offre facturée tout de suite (proration « always_invoice ») porte une ligne
// négative (part non utilisée de l'ancienne offre) et une ligne positive (reste de la période sur la nouvelle) : seule la nouvelle compte.
const offreFacture = f => unique((f.lines && Array.isArray(f.lines.data) ? f.lines.data : []).filter(x => !(typeof x.amount === "number" && x.amount < 0))
  .map(x => { const pd = (x.pricing && x.pricing.price_details) || {}; return offreDuPrix(x.price || x.plan || pd.price, pd.product); }));
const rythmeAbonnement = s => unique((s.items && Array.isArray(s.items.data) ? s.items.data : [])
  .map(x => RYTHME_INTERVALLE[(x.price && x.price.recurring && x.price.recurring.interval) || (x.plan && x.plan.interval)]));
// Statut d'un abonnement (customer.subscription.updated, docs.stripe.com/api/subscriptions/object, champ status) : active et trialing (essai
// des liens « visite ») -> actif ; past_due et unpaid -> impaye ; canceled et incomplete_expired -> resilie ; incomplete, paused et toute autre
// valeur -> en_attente (la base garde alors le statut déjà connu).
const STATUT_ABONNEMENT = { active: "actif", trialing: "actif", past_due: "impaye", unpaid: "impaye", canceled: "resilie", incomplete_expired: "resilie" };

// Remise de lancement supprimée le 15/10/2026 (décision du fondateur) : remise_lancement_fin est toujours envoyée vide. La colonne reste dans la
// base pour un ancien abonnement qui l'aurait reçue (tolérance), rien ne la remplit plus.
const rythmeDe = m => (m && RYTHMES.includes(m.rythme) ? m.rythme : null);
// Rythme réel d'une facture : intervalle du prix de ses lignes (month -> mensuel, year -> annuel), prioritaire sur les métadonnées, que le passage
// mensuel <-> annuel par le portail client ne met pas à jour. Lu à deux endroits (NON CONFIRMÉ contre un vrai compte) : line.price.recurring.interval
// (anciennes versions de l'API) et line.plan.interval ; absent (versions récentes : line.pricing) -> métadonnées.
function rythmeFacture(f, meta) {
  const l = (f.lines && Array.isArray(f.lines.data) ? f.lines.data : []).map(x => (x.price && x.price.recurring && x.price.recurring.interval) || (x.plan && x.plan.interval))
    .map(i => RYTHME_INTERVALLE[i]).filter(Boolean);
  // Passage du mensuel à l'annuel : la facture porte la part non utilisée du mois (crédit, prix mensuel) ET l'année : l'annuel l'emporte.
  return l.includes("annuel") ? "annuel" : l.length ? "mensuel" : rythmeDe(meta);
}

// Client en ligne (21/10/2026) : acheteur venu des boutons du site (lien de paiement sans client_reference_id, donc sans commerce). La base crée
// alors le commerce et l'invitation (bloc « Client créé au paiement en ligne » de schema.sql). On ne transmet QUE l'adresse email, le nom, la langue et le pays :
//   email : customer_details.email (adresse saisie au paiement), sinon customer_email (pré-remplie ; jamais posée par nos liens) ;
//   nom   : customer_details.business_name (nom d'entreprise, si Stripe le rend), sinon customer_details.name (nom saisi au paiement).
// Ni l'adresse postale, ni le numéro de TVA (customer_details.tax_ids), ni le SIREN/BCE (custom_fields, clé « numero_entreprise ») : la base n'a
// aucune colonne pour eux, ils restent dans Stripe, sur le client et ses factures. Champs lus sur la page de l'objet Checkout Session
// (docs.stripe.com/api/checkout/sessions/object, lue le 21/10/2026 : customer_details « The customer details including the customer's tax exempt
// status and the customer's tax IDs », customer_email, client_reference_id, livemode). NON CONFIRMÉ contre un vrai compte : sous-champ
// business_name (versions récentes de l'API, page non dépliée) ; absent, le nom saisi au paiement est pris.
// Langue (27/10/2026, audit du parcours, constat 16 : la première invitation partait en français PUIS en anglais) : celle de la page de paiement,
// session.locale (« The IETF language tag of the locale Checkout is displayed in », docs.stripe.com/api/checkout/sessions/object), posée par le
// site : paramètre « locale » des liens de paiement (« Use locale to display your payment link in a specific language », docs.stripe.com/payment-links/customize,
// lu le 27/10/2026 ; site/app.js l'ajoute selon la langue de la page). Seulement fr, en ou nl (« fr-CA », « en-GB » : la langue avant le tiret) ;
// absente, « auto » ou autre : aucune clé « langue » (la base met le français). NON CONFIRMÉ contre un vrai compte : session.locale remplie par le
// paramètre d'un lien de paiement.
const langueDe = l => { const x = String(l || "").toLowerCase().split("-")[0]; return ["fr", "en", "nl"].includes(x) ? x : null; };
const texteCourt = (s, n) => (typeof s === "string" && s.trim() ? s.trim().replace(/\s+/g, " ").slice(0, n) : null);
function clientEnLigne(o) {
  const cd = o.customer_details && typeof o.customer_details === "object" ? o.customer_details : {};
  const email = texteCourt(cd.email, 254) || texteCourt(o.customer_email, 254), langue = langueDe(o.locale);
  // Pays (31/10/2026, test client Essentiel, tour 5) : customer_details.address.country, code pays ISO à deux lettres de l'adresse de facturation
  // (docs.stripe.com/api/checkout/sessions/object : « Two-letter country code (ISO 3166-1 alpha-2) »). Seul le code part, jamais l'adresse ;
  // la base garde 'BE' pour la Belgique, 'FR' sinon (client_en_ligne). NON CONFIRMÉ contre un vrai compte : adresse demandée par le lien de paiement.
  const ad = cd.address && typeof cd.address === "object" ? cd.address : {}, pays = typeof ad.country === "string" && /^[A-Za-z]{2}$/.test(ad.country) ? ad.country.toUpperCase() : null;
  return Object.assign({ email: email ? email.toLowerCase() : null, nom: texteCourt(cd.business_name, 120) || texteCourt(cd.name, 120) }, langue ? { langue } : {}, pays ? { pays } : {});
}

// Options ponctuelles (22/10/2026 ; moteur/options.json, CGV article 3 bis) : « Visibilité IA » et « Site du restaurant », payées par un lien de
// paiement UNIQUE (mode « payment ») créé par outils/stripe_catalogue.py avec la métadonnée renom_option (et option). Stripe recopie les métadonnées
// du lien sur la session de paiement (docs.stripe.com/api/payment_links/payment_links/create, paramètre metadata, lu le 22/10/2026 : « Metadata
// associated with this Payment Link will automatically be copied to checkout sessions created by this payment link. »). L'option est reconnue par
// cette clé seule, jamais par un identifiant de prix, de produit ou de lien (ils diffèrent entre le mode test et le mode réel). Les lignes
// (line_items) ne sont pas dans l'événement (champ « includable » de l'objet Checkout Session) : rien n'est lu d'elles.
// Paiement : seulement payment_status « paid ». Un moyen de paiement différé (prélèvement) arrive « unpaid » au checkout.session.completed, puis
// « paid » au checkout.session.async_payment_succeeded (« Occurs when a payment intent using a delayed payment method finally succeeds »,
// docs.stripe.com/api/events/types, lu le 22/10/2026) : cet événement doit être coché sur le point de terminaison (étape 78). Montants en centimes :
// amount_subtotal (« before discounts or taxes », donc HT) et amount_total (« after discounts and taxes »).
const OPTIONS_STRIPE = ["visibilite_ia", "site_restaurant"];
const optionDe = m => { const k = m && typeof m === "object" ? m.renom_option || m.option : null; return OPTIONS_STRIPE.includes(k) ? k : null; };
const entier = x => (typeof x === "number" && Number.isFinite(x) ? Math.round(x) : null);
function commandeOption(o, base) {
  const option = optionDe(o.metadata);
  if (!option || !o.id || o.payment_status !== "paid") return null;
  const ref = String(o.client_reference_id || ""), commerce = UUID.test(ref) ? ref.toLowerCase() : null;
  // Commerce cherché par la base comme à l'étape 75 : référence (lien envoyé avec ?client_reference_id=<commerce>), client Stripe, puis adresse email.
  return Object.assign(base, { option, stripe_session: String(o.id), stripe_customer: id(o.customer), commerce_id: commerce, client: clientEnLigne(o),
    montant_ht: entier(o.amount_subtotal), montant_ttc: entier(o.amount_total), devise: typeof o.currency === "string" ? o.currency.slice(0, 3).toLowerCase() : null });
}

// Événement Stripe (objet JSON) -> mise à jour pour appliquer_evenement_stripe (abonnement) ou enregistrer_commande_option (option ponctuelle :
// la mise à jour porte alors « option »), ou null si l'événement n'est pas suivi.
function traduireEvenement(ev) {
  if (!ev || typeof ev !== "object" || !ev.id || !ev.type || !ev.data || !ev.data.object) return null;
  // cree : horodatage de l'événement (secondes) ; la base ne laisse pas un événement plus ancien écraser le statut posé par un plus récent.
  const o = ev.data.object, base = { evenement_id: ev.id, type: ev.type, livemode: !!ev.livemode, cree: typeof ev.created === "number" ? ev.created : null };
  if (ev.type === "checkout.session.async_payment_succeeded") return o.mode === "payment" ? commandeOption(o, base) : null;
  if (ev.type === "checkout.session.completed") {
    if (o.mode === "payment") return commandeOption(o, base);
    if (o.mode !== "subscription" || !id(o.subscription)) return null;
    const ref = String(o.client_reference_id || ""), commerce = UUID.test(ref) ? ref.toLowerCase() : null;
    // Données du client seulement pour un achat SANS référence (bouton du site) : un lien venu de l'espace a déjà son commerce.
    return Object.assign(base, { stripe_subscription: id(o.subscription), stripe_customer: id(o.customer), commerce_id: commerce,
      offre: offreDe(o.metadata), offre_source: offreDe(o.metadata) ? "metadonnees" : null, rythme: rythmeDe(o.metadata), statut: o.payment_status === "paid" || o.payment_status === "no_payment_required" ? "actif" : "en_attente", remise_lancement_fin: null },
      ref ? {} : { client: clientEnLigne(o) });
  }
  // offre_source (27/10/2026) : « prix » quand l'offre est lue sur le prix (vraie après un changement par le portail), « metadonnees » quand elle vient
  // des métadonnées du lien (vraies au paiement, figées ensuite). La base ne change l'offre du commerce que sur un prix (customer.subscription.updated)
  // ou au paiement (checkout.session.completed), jamais sur des métadonnées figées.
  if (ev.type === "invoice.paid" || ev.type === "invoice.payment_failed") {
    const a = abonnementDeFacture(o); if (!a.sub) return null;
    const op = offreFacture(o), offre = op || offreDe(a.meta);
    return Object.assign(base, { stripe_subscription: a.sub, stripe_customer: id(o.customer), commerce_id: null, offre, offre_source: op ? "prix" : offre ? "metadonnees" : null,
      rythme: rythmeFacture(o, a.meta), statut: ev.type === "invoice.paid" ? "actif" : "impaye", remise_lancement_fin: null });
  }
  // Changement d'offre ou de rythme par le portail client (27/10/2026) : nouveau prix de l'abonnement. Une baisse d'offre programmée en fin de
  // période arrive ici le jour où elle s'applique (le prix change à ce moment-là).
  if (ev.type === "customer.subscription.updated") {
    if (!o.id) return null;
    const op = offreAbonnement(o);
    return Object.assign(base, { stripe_subscription: o.id, stripe_customer: id(o.customer), commerce_id: null, offre: op, offre_source: op ? "prix" : null,
      rythme: rythmeAbonnement(o), statut: STATUT_ABONNEMENT[o.status] || "en_attente", remise_lancement_fin: null });
  }
  if (ev.type === "customer.subscription.deleted") {
    if (!o.id) return null;
    const op = offreAbonnement(o), offre = op || offreDe(o.metadata);
    return Object.assign(base, { stripe_subscription: o.id, stripe_customer: id(o.customer), commerce_id: null, offre, offre_source: op ? "prix" : offre ? "metadonnees" : null, statut: "resilie", remise_lancement_fin: null });
  }
  return null;
}

